# ── Read Data ──────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10

# Round prices to 2 decimal places for cleanliness
df['Crude_Oil_Price'] = df['Crude_Oil_Price'].round(2)

prices = df['Crude_Oil_Price'].values
dates = df['Date'].values

# ── KPI Calculations ───────────────────────────────────────────
price_min = prices.min()
price_max = prices.max()
price_range = price_max - price_min
price_mean = prices.mean()
price_median = np.median(prices)
price_std = prices.std(ddof=0)
price_p25 = np.percentile(prices, 25)
price_p75 = np.percentile(prices, 75)

first_price = df['Crude_Oil_Price'].iloc[0]
last_price = df['Crude_Oil_Price'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]

years_elapsed = (last_date - first_date).days / 365.25
cagr = ((last_price / first_price) ** (1 / years_elapsed) - 1) * 100

# MoM changes
df['MoM_Change'] = df['Crude_Oil_Price'].diff()
df['MoM_Change_Pct'] = df['Crude_Oil_Price'].pct_change() * 100
max_mom_abs = df['MoM_Change'].abs().max()
max_mom_idx = df['MoM_Change'].abs().idxmax()
max_mom_row = df.iloc[max_mom_idx]
max_mom_abs_val = max_mom_row['MoM_Change']
max_mom_abs_pct = max_mom_row['MoM_Change_Pct']

# YoY changes
df['YoY_Change'] = df['Crude_Oil_Price'].diff(12)
df['YoY_Change_Pct'] = df['Crude_Oil_Price'].pct_change(12) * 100
max_yoy_abs = df['YoY_Change'].abs().max()
max_yoy_idx = df['YoY_Change'].abs().idxmax()
max_yoy_row = df.iloc[max_yoy_idx]

# Decade analysis
decade_stats = df.groupby('Decade').agg(
    Avg_Price=('Crude_Oil_Price', 'mean'),
